GO gsparse(const SCRow&row){GO out;for(size_t i=0;i<row.size();++i){int c=gsmall(row[i]);if(c)out.emplace_back(int(i),c);}return out;}
Point gmultiple(Point p,int n){if(n<0){p.y=-p.y;n=-n;}Point out;while(n--){out=add(out,p);}return out;}
